/**
 * Drag-to-resize / double-click-to-autosize grip used by DataTableHeader and
 * DataTableVirtualizedHeader when `enableColumnResizing` is on. Lives in core
 * so both bodies can import it without pulling the opt-in marker package.
 */
import { type Header } from "@tanstack/react-table"
import * as React from "react"
import { cn } from "@/lib/utils"
import { DEFAULT_MAX_COLUMN_SIZE, DEFAULT_MIN_COLUMN_SIZE } from "./constants"

/** Room for cell chrome the text measurement doesn't cover. */
const AUTOSIZE_CELL_PADDING = 24 // horizontal padding + buffer
const AUTOSIZE_HEADER_CHROME = 52 // sort/menu trigger + resize grip

/** Re-export for consumers that imported sizes from this module. */
export { DEFAULT_MAX_COLUMN_SIZE, DEFAULT_MIN_COLUMN_SIZE }

/** Keyboard resize step (px); the larger step applies while Shift is held. */
const KEYBOARD_RESIZE_STEP = 8
const KEYBOARD_RESIZE_STEP_LARGE = 40

/**
 * Tightest width that fits every TEXT node in an element. Uses a DOM Range
 * so `w-full` + `truncate` wrappers — whose `scrollWidth` echoes the current
 * cell width — don't hide the natural content width. Autosize can grow AND
 * shrink to fit.
 */
function widestTextWidth(el: Element): number {
  const range = document.createRange()
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT)
  let max = 0
  for (let n = walker.nextNode(); n; n = walker.nextNode()) {
    if (!n.textContent || n.textContent.trim() === "") continue
    range.selectNodeContents(n)
    max = Math.max(max, range.getBoundingClientRect().width)
  }
  return max
}

/**
 * Autosize a column to fit its content — measures the widest rendered
 * cell/header text (mounted cells only — for virtualized tables, what's on
 * screen) and sets that column's size.
 */
function autosizeColumn<TData>(
  header: Header<TData, unknown>,
  handle: Element,
) {
  const root = handle.closest('[data-slot="table"]')
  if (!root) return
  const cells = root.querySelectorAll<HTMLElement>(
    `[data-col-id="${CSS.escape(header.column.id)}"]`,
  )
  let content = 0
  cells.forEach(c => {
    const isHeader = c.getAttribute("data-slot") === "table-head"
    const chrome = isHeader ? AUTOSIZE_HEADER_CHROME : AUTOSIZE_CELL_PADDING
    content = Math.max(content, widestTextWidth(c) + chrome)
  })
  if (content <= 0) return
  const def = header.column.columnDef
  const width = Math.min(
    Math.max(Math.ceil(content), def.minSize ?? DEFAULT_MIN_COLUMN_SIZE),
    def.maxSize ?? DEFAULT_MAX_COLUMN_SIZE,
  )
  header
    .getContext()
    .table.setColumnSizing(prev => ({ ...prev, [header.column.id]: width }))
}

/**
 * Drag-to-resize / double-click-to-autosize grip on a header's right edge.
 * Keyboard-operable (WAI-ARIA window-splitter): focusable, Arrow Left/Right
 * nudge the width (Shift = larger step), Enter autosizes; exposes
 * `aria-value*`.
 */
export interface DataTableColumnResizeHandleProps<TData> {
  header: Header<TData, unknown>
  /**
   * This column is currently the flex (fill) column. Flex columns have no width
   * TanStack can drive, so they resize through a custom pointer drag that starts
   * from the rendered width (no jump) and, on release, writes an explicit width
   * — which pins the column and hands the fill to the next eligible column.
   */
  isFlex?: boolean
  /**
   * Drive the resize preview line during a flex drag (from the DataTable
   * context). Passed `{ resizingColumnId, deltaOffset }` while dragging, `null`
   * on release.
   */
  setResizePreview?: (
    info: { resizingColumnId: string | null; deltaOffset: number } | null,
  ) => void
}

export function DataTableColumnResizeHandle<TData>({
  header,
  isFlex = false,
  setResizePreview,
}: DataTableColumnResizeHandleProps<TData>) {
  const isResizing = header.column.getIsResizing()
  const resize = header.getResizeHandler()
  const def = header.column.columnDef
  const min = def.minSize ?? DEFAULT_MIN_COLUMN_SIZE
  const max = def.maxSize ?? DEFAULT_MAX_COLUMN_SIZE

  // ARIA value: `getSize()` is wrong for a column without an explicit
  // `columnSizing` entry — a flex column renders at whatever fills the
  // container, and header-fit can floor an un-resized column wider than its
  // declared size. Measure the rendered width when the handle gains focus so
  // screen readers hear the real width; once an entry exists, `getSize()` is
  // the truth again (user choice wins, render and ARIA agree).
  const [focusedWidth, setFocusedWidth] = React.useState<number | null>(null)
  const hasExplicitWidth =
    header.getContext().table.getState().columnSizing[header.column.id] != null
  const ariaValueNow = Math.round(
    hasExplicitWidth
      ? header.column.getSize()
      : (focusedWidth ?? header.column.getSize()),
  )

  // `fallbackWidth` seeds the first nudge for a flex column (no `columnSizing`
  // entry yet) from its rendered width so the arrow key doesn't jump it to the
  // declared `size`. Non-flex columns fall back to `getSize()` as before.
  const nudge = (delta: number, fallbackWidth?: number) => {
    header.getContext().table.setColumnSizing(prev => {
      const current =
        prev[header.column.id] ?? fallbackWidth ?? header.column.getSize()
      const next = Math.min(Math.max(current + delta, min), max)
      return { ...prev, [header.column.id]: next }
    })
  }

  // Tear down an in-flight flex drag if the handle unmounts mid-drag (route
  // change, dialog close): the window listeners must not linger, and the
  // eventual pointerup must not commit a width to a table that no longer
  // exists (a consumer's `onColumnSizingChange` could persist it).
  const flexDragTeardownRef = React.useRef<(() => void) | null>(null)
  React.useEffect(() => () => flexDragTeardownRef.current?.(), [])

  // Custom drag for the flex column: measure its rendered (filled) width as the
  // start so there's no jump, follow the cursor via the preview line, and write
  // an explicit width on release (which releases it from flex).
  const startFlexResize = (
    startClientX: number,
    handleEl: HTMLElement | null,
  ) => {
    const thEl = handleEl?.closest<HTMLElement>("[data-col-id]")
    if (!thEl || !setResizePreview) return
    const startWidth = thEl.getBoundingClientRect().width
    const id = header.column.id
    setResizePreview({ resizingColumnId: id, deltaOffset: 0 })
    const onMove = (ev: PointerEvent) => {
      setResizePreview({
        resizingColumnId: id,
        deltaOffset: ev.clientX - startClientX,
      })
    }
    const teardown = () => {
      flexDragTeardownRef.current = null
      window.removeEventListener("pointermove", onMove)
      window.removeEventListener("pointerup", onUp)
      window.removeEventListener("pointercancel", onCancel)
      setResizePreview(null)
    }
    flexDragTeardownRef.current = teardown
    // Commit the new width only on a real release. A cancelled pointer (e.g. the
    // browser stealing the gesture) just tears down and keeps the column flexing.
    const onUp = (ev: PointerEvent) => {
      const next = Math.min(
        Math.max(startWidth + (ev.clientX - startClientX), min),
        max,
      )
      header
        .getContext()
        .table.setColumnSizing(prev => ({ ...prev, [id]: next }))
      teardown()
    }
    const onCancel = () => teardown()
    window.addEventListener("pointermove", onMove)
    window.addEventListener("pointerup", onUp)
    window.addEventListener("pointercancel", onCancel)
  }

  return (
    <div
      data-slot="column-resize-handle"
      role="separator"
      aria-orientation="vertical"
      aria-label="Resize column (arrow keys, or double-click to fit)"
      aria-valuenow={ariaValueNow}
      aria-valuemin={min}
      // A flex column can legitimately render wider than the declared
      // `maxSize` (fill ignores it), so keep the ARIA range valid.
      aria-valuemax={Math.max(max, ariaValueNow)}
      tabIndex={0}
      onFocus={e => {
        const width = e.currentTarget
          .closest("[data-col-id]")
          ?.getBoundingClientRect().width
        setFocusedWidth(width ?? null)
      }}
      onBlur={() => setFocusedWidth(null)}
      onMouseDown={e => {
        // Keep column-DnD header listeners from treating a resize drag as a
        // reorder start (handle lives inside the sortable `<th>`).
        e.stopPropagation()
        // Flex columns resize via the pointer-based custom drag below.
        if (!isFlex) resize(e)
      }}
      onTouchStart={e => {
        e.stopPropagation()
        if (!isFlex) resize(e)
      }}
      onDoubleClick={e => autosizeColumn(header, e.currentTarget)}
      onClick={e => e.stopPropagation()}
      onPointerDown={e => {
        e.stopPropagation()
        if (isFlex) {
          e.preventDefault()
          startFlexResize(e.clientX, e.currentTarget)
        }
      }}
      onKeyDown={e => {
        const step = e.shiftKey
          ? KEYBOARD_RESIZE_STEP_LARGE
          : KEYBOARD_RESIZE_STEP
        // Flex columns have no `columnSizing` entry, so seed the first nudge
        // from the rendered width to avoid jumping to the declared `size`.
        const fallbackWidth = isFlex
          ? e.currentTarget.closest("[data-col-id]")?.getBoundingClientRect()
              .width
          : undefined
        if (e.key === "ArrowLeft") {
          e.preventDefault()
          nudge(-step, fallbackWidth)
        } else if (e.key === "ArrowRight") {
          e.preventDefault()
          nudge(step, fallbackWidth)
        } else if (e.key === "Enter") {
          e.preventDefault()
          autosizeColumn(header, e.currentTarget)
        }
      }}
      className="group/resize absolute top-0 right-0 z-10 flex h-full w-2 cursor-col-resize touch-none justify-end outline-none select-none"
    >
      {/* Idle: invisible — an always-on grip bar reads as a header divider
          and drifts 1–2px from real cell `border-r`. Show on hover/focus/drag. */}
      <div
        className={cn(
          "my-1.5 w-px rounded bg-border opacity-0 transition-all",
          "group-hover/resize:my-0 group-hover/resize:w-0.5 group-hover/resize:bg-primary group-hover/resize:opacity-100",
          "group-focus-visible/resize:my-0 group-focus-visible/resize:w-0.5 group-focus-visible/resize:bg-primary group-focus-visible/resize:opacity-100",
          isResizing && "my-0 w-0.5 bg-primary opacity-100",
        )}
      />
    </div>
  )
}

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */
import type { Column, ColumnSizingState, Table } from "@tanstack/react-table"

/**
 * Resolve which column(s) should flex to fill the leftover row width.
 *
 * Flex fill is ON BY DEFAULT for resizable tables. A flex column renders with
 * no explicit width, so under `table-layout: fixed` it soaks up the surplus:
 * the table fills its container and a trailing actions column pins to the right
 * edge instead of leaving dead space. It's pure layout — never writes
 * `columnSizing`, so no persistence side effects.
 *
 * Selection: when no column opts in explicitly, the DEFAULT is the first
 * non-pinned, resizable column (the primary text column). Selection / expand /
 * actions columns are non-resizable (`enableResizing: false`), so they're
 * skipped automatically; the default lands on the first real data column.
 *
 * Overrides:
 * - `meta: { flex: true }` on a column flexes THAT column instead of the
 *   default — use it when the primary column isn't the first one (e.g. a table
 *   whose first columns are narrow codes/dates and a later column should grow).
 * - `meta: { flex: false }` opts a column out of ever being auto-picked.
 * - `meta: { disableFlexFill: true }` on the table (TableMeta) turns fill off
 *   entirely — for a wide table meant to scroll horizontally rather than fill.
 *
 * Returns the set of column ids to render widthless (empty when fill is off or
 * no eligible column exists — the table then sizes to its columns as before).
 */
export function resolveFlexColumnIds<TData>(
  table: Table<TData>,
): ReadonlySet<string> {
  const ids = new Set<string>()
  // Flex only applies under the fixed layout that resizing turns on.
  if (!table.options.enableColumnResizing) return ids
  if (table.options.meta?.disableFlexFill) return ids

  const leafColumns = table.getVisibleLeafColumns()
  // A column the user has explicitly resized is fixed at their width and never
  // flexes — so dragging a flex column pins it and hands the fill to the next
  // eligible column, keeping the table full.
  const columnSizing = table.getState().columnSizing

  // Explicit opt-in wins: flex the marked column(s) unless the user resized it.
  // A pinned column can't flex (sticky offsets need a real width), so skip it
  // and fall through to the auto-pick — a marked-but-pinned column shouldn't
  // strand the table without a fill column.
  let hasExplicit = false
  for (const column of leafColumns) {
    if (
      column.columnDef.meta?.flex === true &&
      !column.getIsPinned() &&
      columnSizing[column.id] == null
    ) {
      ids.add(column.id)
      hasExplicit = true
    }
  }
  if (hasExplicit) return ids

  // Default: the first non-pinned, resizable, un-resized, non-opted-out column.
  const auto = leafColumns.find(
    column =>
      column.getCanResize() &&
      !column.getIsPinned() &&
      column.columnDef.meta?.flex !== false &&
      columnSizing[column.id] == null,
  )
  if (auto) ids.add(auto.id)
  return ids
}

/**
 * The width to render for a single column. Centralizes the flex + header-fit
 * rules so the header, body cells, and the min-width lock all agree.
 *
 * - Off (no resizing): the declared `size` (or auto when unset).
 * - Flex column: no width — it fills the leftover row width.
 * - Resized by the user: exactly `getSize()` — their choice wins, even if it's
 *   narrower than the header (matches how spreadsheet grids let you shrink).
 * - Otherwise: floored at the header's natural width (`headerMinWidths`) so the
 *   label never truncates on load. Pure layout — `headerMinWidths` is measured,
 *   never written back into `columnSizing`, so nothing persists or goes stale.
 */
export function resolveColumnWidth<TData>(
  column: Column<TData>,
  params: {
    resizing: boolean
    isFlex: boolean
    columnSizing: ColumnSizingState
    headerMinWidths: ReadonlyMap<string, number>
  },
): number | string | undefined {
  const size = column.columnDef.size
  // Off (no resizing): the declared `size`. Flex only means "fill the surplus"
  // under the fixed layout that resizing turns on, so a flex column keeps its
  // declared size here — check resizing before flex.
  if (!params.resizing) return size ? `${size}px` : undefined
  if (params.isFlex) return undefined
  const base = column.getSize()
  if (params.columnSizing[column.id] != null) return base
  const headerMin = params.headerMinWidths.get(column.id) ?? 0
  return headerMin > base ? headerMin : base
}

"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */
import type { Column, Table } from "@tanstack/react-table"
import * as React from "react"

import { formatLabel } from "./format"

// Non-label chrome inside a header cell: horizontal padding + the resize
// handle + a little slack. Added to the measured label width so the floor
// leaves the label breathing room, not a pixel-tight fit.
const BASE_HEADER_CHROME_PX = 28
// A sortable column also renders a sort trigger next to the label.
const SORT_AFFORDANCE_PX = 24

const EMPTY_MIN_WIDTHS: ReadonlyMap<string, number> = new Map()

// One reusable off-DOM canvas: `measureText` never touches layout, so measuring
// every header costs no reflow (unlike reading `scrollWidth` per cell).
let measureCanvas: HTMLCanvasElement | null = null
function getMeasureContext(): CanvasRenderingContext2D | null {
  if (typeof document === "undefined") return null
  if (!measureCanvas) measureCanvas = document.createElement("canvas")
  return measureCanvas.getContext("2d")
}

/**
 * The label text a column renders in its header. Mirrors the composable
 * title's precedence (`useDerivedColumnTitle`): `meta.label`, else a plain
 * string `header`, else the formatted column id — the same fallback
 * `DataTableColumnTitle` renders when nothing else is set. One gap this can't
 * see: a JSX `<DataTableColumnTitle title="..." />` override lives in rendered
 * output, not the column def — mirror such overrides into `meta.label` so
 * header-fit measures the right string.
 */
function headerLabel<TData>(column: Column<TData, unknown>): string | null {
  const columnDef = column.columnDef
  if (columnDef.meta?.label) return columnDef.meta.label
  if (typeof columnDef.header === "string") return columnDef.header
  return formatLabel(column.id)
}

/** Content equality so a re-measure with identical results keeps identity. */
function minWidthsEqual(
  a: ReadonlyMap<string, number>,
  b: ReadonlyMap<string, number>,
): boolean {
  if (a.size !== b.size) return false
  for (const [id, width] of b) {
    if (a.get(id) !== width) return false
  }
  return true
}

/**
 * Measure the natural width each column's header needs so a column is never
 * rendered so narrow that its label truncates on load (header-fit).
 *
 * Returns `columnId -> minimum width in px` (label width + header chrome). The
 * caller floors each un-resized column at this width; a column the user has
 * explicitly resized is left alone. Pure measurement — nothing is written to
 * `columnSizing`, so it never persists or goes stale.
 *
 * Recomputes only when the visible columns, their labels, or the header font
 * change — measurement itself is O(columns) with zero reflow.
 */
export function useHeaderMinWidths<TData>(
  table: Table<TData>,
  scrollElement: HTMLElement | null,
  enabled: boolean,
): ReadonlyMap<string, number> {
  const [minWidths, setMinWidths] =
    React.useState<ReadonlyMap<string, number>>(EMPTY_MIN_WIDTHS)

  const leafColumns = table.getVisibleLeafColumns()
  // Signature: recompute when the visible set, a label, or sortability changes.
  const signature = leafColumns
    .map(c => `${c.id}:${headerLabel(c) ?? ""}:${c.getCanSort() ? 1 : 0}`)
    .join("|")

  // Measure-then-store is the canonical layout-measurement pattern (same as
  // `useColumnAutoFit`): it needs the rendered DOM (header font), so it can't
  // run during render. The one extra commit it triggers is intended.
  React.useLayoutEffect(() => {
    // Content-equal results keep the previous Map identity — downstream
    // `columnWidths` memos and memoized body rows only re-render when a floor
    // actually changed, not on every re-measure.
    const store = (next: ReadonlyMap<string, number>) =>
      setMinWidths(prev => (minWidthsEqual(prev, next) ? prev : next))

    if (!enabled || !scrollElement) {
      store(EMPTY_MIN_WIDTHS)
      return
    }

    const ctx = getMeasureContext()
    // Read the real header font (family/size/weight) so measurement matches the
    // rendered label. Prefer the composable title element (semibold); fall back
    // to the header cell itself so raw string headers are still measurable.
    const fontEl =
      scrollElement.querySelector<HTMLElement>(
        'thead [data-slot="column-title"]',
      ) ?? scrollElement.querySelector<HTMLElement>("thead th[data-col-id]")
    if (!ctx || !fontEl) {
      // No header rendered yet / nothing to measure — drop any stale floors.
      store(EMPTY_MIN_WIDTHS)
      return
    }
    const cs = getComputedStyle(fontEl)
    ctx.font = `${cs.fontStyle} ${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`

    const next = new Map<string, number>()
    for (const column of leafColumns) {
      // Floors apply only to resizable columns. Fixed utility columns
      // (selection, actions, gutters — `enableResizing: false`) keep their
      // declared size: they often have no visible label, and the formatted-id
      // fallback would otherwise invent a phantom floor for them.
      if (!column.getCanResize()) continue
      const label = headerLabel(column)
      if (!label) continue
      const textWidth = ctx.measureText(label).width
      const chrome =
        BASE_HEADER_CHROME_PX + (column.getCanSort() ? SORT_AFFORDANCE_PX : 0)
      next.set(column.id, Math.ceil(textWidth) + chrome)
    }
    store(next)
    // `leafColumns` identity churns each render; `signature` is the stable key.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enabled, scrollElement, signature])

  return minWidths
}

